using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;
namespace BeamScheduleFormatter {
class SlabFormatterForm:Form {
 readonly DataGridView grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,RowHeadersVisible=false,AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells};readonly TextBox prefix=new TextBox{Width=85,Text="2S",CharacterCasing=CharacterCasing.Upper};readonly TextBox floor=new TextBox{Width=240,Text="SECOND FLOOR",CharacterCasing=CharacterCasing.Upper};readonly CheckBox merge=new CheckBox{Text="Merge identical rows",Checked=true,AutoSize=true};readonly Label source=new Label{Dock=DockStyle.Top,Height=45,Padding=new Padding(12),Text="Loaded DXF: none"};readonly Label status=new Label{Dock=DockStyle.Bottom,Height=34,Padding=new Padding(10)};readonly PictureBox cad=new PictureBox{SizeMode=PictureBoxSizeMode.AutoSize};readonly Button export=new Button{Text="Export revised DXF",AutoSize=true,Enabled=false};string raw;SlabFormatResult result;bool busy;
 public SlabFormatterForm(){if(!AccessCodes.CanUseApp(ProgramAccess.SlabFormatter))throw new Exception("Schedule Formatter access required.");AppBrand.Apply(this);Text="Slab Schedule Formatter | DTCE Tool Kit";Size=new Size(1420,900);MinimumSize=new Size(1100,700);Font=new Font("Segoe UI",9.5f);StartPosition=FormStartPosition.CenterScreen;var title=new Label{Text="SLAB SCHEDULE FORMATTER",Dock=DockStyle.Top,Height=54,Padding=new Padding(12),Font=new Font("Segoe UI",18,FontStyle.Bold),ForeColor=PowTheme.Ink};var tools=new FlowLayoutPanel{Dock=DockStyle.Top,Height=88,Padding=new Padding(8),AutoScroll=true};var load=new Button{Text="Load source DXF",AutoSize=true};load.Click+=(s,e)=>Choose();tools.Controls.Add(load);tools.Controls.Add(new Label{Text="Prefix",AutoSize=true,Padding=new Padding(4,8,0,0)});tools.Controls.Add(prefix);tools.Controls.Add(new Label{Text="Floor title",AutoSize=true,Padding=new Padding(4,8,0,0)});tools.Controls.Add(floor);tools.Controls.Add(merge);var build=new Button{Text="Build preview",AutoSize=true};build.Click+=(s,e)=>Build();tools.Controls.Add(build);tools.Controls.Add(export);export.Click+=(s,e)=>Export();var notes=new Label{Dock=DockStyle.Top,Height=47,Padding=new Padding(10),Text="Matching thickness and all 9 reinforcement cells are grouped. New marks use prefix-001; original slab marks appear outside the table on the right. Headers follow your slab template; body text is regular. No stirrup processing."};var tabs=new NavigationTabs{Dock=DockStyle.Fill};var values=new TabPage("Schedule values");var layout=new TabPage("DXF preview");var panel=new Panel{Dock=DockStyle.Fill,AutoScroll=true,BackColor=Color.FromArgb(33,40,46)};panel.Controls.Add(cad);layout.Controls.Add(panel);values.Controls.Add(grid);tabs.TabPages.Add(values);tabs.TabPages.Add(layout);foreach(string header in new[]{"New slab mark","Thickness mm"}.Concat(SlabScheduleReader.Columns).Concat(new[]{"Original slab marks"})){grid.Columns.Add(header,header);}grid.Columns[0].Width=115;grid.Columns[0].Frozen=true;grid.Columns[1].Width=95;for(int c=2;c<11;c++)grid.Columns[c].Width=155;grid.Columns[11].Visible=false;var originals=new TextBox{Dock=DockStyle.Bottom,Height=62,Multiline=true,ReadOnly=true,Font=new Font("Consolas",10),ScrollBars=ScrollBars.Vertical};values.Controls.Add(originals);grid.SelectionChanged+=(sender,args)=>{originals.Text=grid.CurrentRow==null?"":"Original slab marks: "+Convert.ToString(grid.CurrentRow.Cells[11].Value);};grid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;GridAppearance.Apply(grid);Controls.Add(tabs);Controls.Add(notes);Controls.Add(source);Controls.Add(tools);Controls.Add(title);Controls.Add(status);prefix.Leave+=(s,e)=>{string value=prefix.Text.Trim().ToUpperInvariant();if(System.Text.RegularExpressions.Regex.IsMatch(value,@"^\d+S$"))floor.Text=Engine.FloorFor(value.Substring(0,value.Length-1)+"B");};prefix.TextChanged+=(s,e)=>InvalidateOutput();floor.TextChanged+=(s,e)=>InvalidateOutput();merge.CheckedChanged+=(s,e)=>InvalidateOutput();FormClosed+=(s,e)=>{if(cad.Image!=null)cad.Image.Dispose();};
 #if !ADMIN_APP
 var renewal=new AccessRenewal(this);FormClosed+=(s,e)=>renewal.Dispose();
 #endif
 }
 void Guard(){if(!AccessCodes.CanUseApp(ProgramAccess.SlabFormatter))throw new Exception("Renew Schedule Formatter access.");}
 void InvalidateOutput(){result=null;export.Enabled=false;grid.Rows.Clear();if(cad.Image!=null){cad.Image.Dispose();cad.Image=null;}status.Text="Build preview to apply the current prefix, floor title and grouping.";}
 void Choose(){try{Guard();using(var dialog=new OpenFileDialog{Filter="Slab schedule DXF|*.dxf"})if(dialog.ShowDialog(this)==DialogResult.OK){string input=File.ReadAllText(dialog.FileName);SlabScheduleReader.Read(input);raw=input;source.Text="Loaded DXF: "+Path.GetFileName(dialog.FileName);InvalidateOutput();Build();}}catch(Exception x){MessageBox.Show(this,x.Message,"Slab source");}}
 internal void LoadSource(string input,string name){SlabScheduleReader.Read(input);raw=input;source.Text="Loaded DXF: "+name;Build();}
 void Build(){if(busy)return;busy=true;try{Guard();if(raw==null)throw new Exception("Load an original slab schedule DXF first.");InvalidateOutput();var built=SlabFormatter.Build(raw,prefix.Text,floor.Text,merge.Checked);foreach(var group in built.Groups){var values=new object[12];values[0]=group.Mark;values[1]=group.Schedule.Thickness.ToString("0.00");for(int c=0;c<9;c++)values[c+2]=SlabFormatter.BarText(group.Schedule.Bars[c]).Replace("%%C","\u00d8");values[11]=group.Originals;grid.Rows.Add(values);}cad.Image=Preview.Render(built.Drawing);result=built;export.Enabled=true;status.Text=built.SourceCount+" original slab marks > "+built.Groups.Count+" output rows | "+prefix.Text+" | "+floor.Text;}catch(Exception x){MessageBox.Show(this,x.Message,"Slab preview");}finally{busy=false;}}
 void Export(){try{Guard();if(result==null)throw new Exception("Build preview first.");using(var dialog=new SaveFileDialog{Filter="Revised slab DXF|*.dxf",FileName=prefix.Text+" Slab Schedule - Revised.dxf"})if(dialog.ShowDialog(this)==DialogResult.OK){SlabFormatter.Export(result,dialog.FileName);status.Text="Exported: "+dialog.FileName;}}catch(Exception x){MessageBox.Show(this,x.Message,"Slab export");}}
}
}

